// Adapted from shadcn/ui (MIT). See SHADCN-LICENSE.txt and upstream provenance.
"use client";

import * as React from "react";
import { cn } from "./utils";
import { CheckIcon, ChevronRightIcon, CircleIcon } from "lucide-react";
import { DropdownMenu as DropdownMenuPrimitive } from "./primitive-dropdown-menu";

function DropdownMenu({
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.Root>) {
  return <DropdownMenuPrimitive.Root data-slot="dropdown-menu" {...props} />;
}

function DropdownMenuPortal({
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.Portal>) {
  return (
    <DropdownMenuPrimitive.Portal data-slot="dropdown-menu-portal" {...props} />
  );
}

function DropdownMenuTrigger({
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.Trigger>) {
  return (
    <DropdownMenuPrimitive.Trigger
      data-slot="dropdown-menu-trigger"
      {...props}
    />
  );
}

function DropdownMenuContent({
  className,
  sideOffset = 4,
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.Content>) {
  return (
    <DropdownMenuPrimitive.Portal>
      <DropdownMenuPrimitive.Content
        data-slot="dropdown-menu-content"
        sideOffset={sideOffset}
        className={cn("roc-ui", className)}
        {...props}
      />
    </DropdownMenuPrimitive.Portal>
  );
}

function DropdownMenuGroup({
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.Group>) {
  return (
    <DropdownMenuPrimitive.Group data-slot="dropdown-menu-group" {...props} />
  );
}

function DropdownMenuItem({
  className,
  inset,
  variant = "default",
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.Item> & {
  inset?: boolean;
  variant?: "default" | "destructive";
}) {
  return (
    <DropdownMenuPrimitive.Item
      data-slot="dropdown-menu-item"
      data-inset={inset}
      data-variant={variant}
      className={cn("roc-ui", className)}
      {...props}
    />
  );
}

function DropdownMenuCheckboxItem({
  className,
  children,
  checked,
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.CheckboxItem>) {
  return (
    <DropdownMenuPrimitive.CheckboxItem
      data-slot="dropdown-menu-checkbox-item"
      className={cn("roc-ui", className)}
      checked={checked}
      {...props}
    >
      <span className="roc-ui">
        <DropdownMenuPrimitive.ItemIndicator>
          <CheckIcon className="roc-ui-icon" />
        </DropdownMenuPrimitive.ItemIndicator>
      </span>
      {children}
    </DropdownMenuPrimitive.CheckboxItem>
  );
}

function DropdownMenuRadioGroup({
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.RadioGroup>) {
  return (
    <DropdownMenuPrimitive.RadioGroup
      data-slot="dropdown-menu-radio-group"
      {...props}
    />
  );
}

function DropdownMenuRadioItem({
  className,
  children,
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.RadioItem>) {
  return (
    <DropdownMenuPrimitive.RadioItem
      data-slot="dropdown-menu-radio-item"
      className={cn("roc-ui", className)}
      {...props}
    >
      <span className="roc-ui">
        <DropdownMenuPrimitive.ItemIndicator>
          <CircleIcon className="roc-ui-icon" />
        </DropdownMenuPrimitive.ItemIndicator>
      </span>
      {children}
    </DropdownMenuPrimitive.RadioItem>
  );
}

function DropdownMenuLabel({
  className,
  inset,
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.Label> & {
  inset?: boolean;
}) {
  return (
    <DropdownMenuPrimitive.Label
      data-slot="dropdown-menu-label"
      data-inset={inset}
      className={cn("roc-ui", className)}
      {...props}
    />
  );
}

function DropdownMenuSeparator({
  className,
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.Separator>) {
  return (
    <DropdownMenuPrimitive.Separator
      data-slot="dropdown-menu-separator"
      className={cn("roc-ui", className)}
      {...props}
    />
  );
}

function DropdownMenuShortcut({
  className,
  ...props
}: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="dropdown-menu-shortcut"
      className={cn("roc-ui", className)}
      {...props}
    />
  );
}

function DropdownMenuSub({
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.Sub>) {
  return <DropdownMenuPrimitive.Sub data-slot="dropdown-menu-sub" {...props} />;
}

function DropdownMenuSubTrigger({
  className,
  inset,
  children,
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.SubTrigger> & {
  inset?: boolean;
}) {
  return (
    <DropdownMenuPrimitive.SubTrigger
      data-slot="dropdown-menu-sub-trigger"
      data-inset={inset}
      className={cn("roc-ui", className)}
      {...props}
    >
      {children}
      <ChevronRightIcon className="roc-ui-icon" />
    </DropdownMenuPrimitive.SubTrigger>
  );
}

function DropdownMenuSubContent({
  className,
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.SubContent>) {
  return (
    <DropdownMenuPrimitive.SubContent
      data-slot="dropdown-menu-sub-content"
      className={cn("roc-ui", className)}
      {...props}
    />
  );
}

export {
  DropdownMenu,
  DropdownMenuPortal,
  DropdownMenuTrigger,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuLabel,
  DropdownMenuItem,
  DropdownMenuCheckboxItem,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuShortcut,
  DropdownMenuSub,
  DropdownMenuSubTrigger,
  DropdownMenuSubContent,
};

import "./dropdown-menu.css";

import { clsx, type ClassValue } from "clsx";
/** Scoped CSS needs no Tailwind runtime or host configuration. */
export function cn(...inputs: ClassValue[]) {
  return clsx(inputs);
}

"use client";
// ROC primitive: a menu opened from a button. Behaviour from Base UI.
import { Menu as Base } from "@base-ui/react/menu";
import { createMenu } from "./primitive-menu-core";

export const DropdownMenu = createMenu(Base, "dropdown-menu", "button");

"use client";
// ROC primitive: shared adapter that gives Base UI's Menu parts (and ContextMenu's, which
// share them) the Content/Item/CheckboxItem/ItemIndicator shape ROC components use.
import * as React from "react";
import { createContent, isNativeButton, renderChild } from "./primitive-popup";

type Div = Omit<React.ComponentProps<"div">, "ref"> & { ref?: React.Ref<any> };
type Details = { reason: string; cancel: () => void };

const KindContext = React.createContext<"checkbox" | "radio">("checkbox");
/** Set by an item whose `onSelect` called preventDefault: keep the menu open. */
const KeepOpen = React.createContext<{ current: boolean }>({ current: false });

export function createMenu(
  Base: any,
  prefix: string,
  triggerTag: "button" | "span",
  /** Context menus open to the right of the pointer, like Radix. */
  defaults: { side?: "right"; align?: "start" } = {},
) {
  const BaseContent = createContent(
    { Positioner: Base.Positioner, Popup: Base.Popup },
    prefix,
  );
  function Content(props: React.ComponentProps<typeof BaseContent>) {
    return <BaseContent aria-orientation="vertical" {...defaults} {...props} />;
  }

  function useGuard(onOpenChange?: (open: boolean) => void) {
    const keepOpen = React.useContext(KeepOpen);
    return (next: boolean, details: Details) => {
      if (!next && details?.reason === "item-press" && keepOpen.current) {
        keepOpen.current = false;
        details.cancel();
        return;
      }
      keepOpen.current = false;
      onOpenChange?.(next);
    };
  }

  type RootProps = {
    open?: boolean;
    defaultOpen?: boolean;
    onOpenChange?: (open: boolean) => void;
    modal?: boolean;
    children?: React.ReactNode;
  };

  function Guarded({ Part, onOpenChange, ...props }: RootProps & { Part: any }) {
    const guard = useGuard(onOpenChange);
    return <Part {...props} onOpenChange={guard} />;
  }

  function Root(props: RootProps) {
    const keepOpen = React.useRef(false);
    return (
      <KeepOpen.Provider value={keepOpen}>
        <Guarded Part={Base.Root} {...props} />
      </KeepOpen.Provider>
    );
  }

  function Sub({ modal: _modal, ...props }: RootProps) {
    return <Guarded Part={Base.SubmenuRoot} {...props} />;
  }

  type TriggerProps = Omit<React.ComponentProps<"button">, "ref"> & {
    asChild?: boolean;
    ref?: React.Ref<any>;
  };
  function triggerPart(
    Part: any,
    tag: "button" | "span" | "div",
    extra?: (child: React.ReactElement) => object,
  ) {
    return function Trigger({ asChild, children, ...props }: TriggerProps) {
      if (asChild && React.isValidElement(children)) {
        const child = children as React.ReactElement;
        return (
          <Part
            {...(props as object)}
            {...extra?.(child)}
            render={renderChild(child, (state) => state.open ?? state.popupOpen)}
          />
        );
      }
      const Tag = tag as React.ElementType;
      return (
        <Part
          {...(props as object)}
          render={(p: Record<string, any>, state: { open?: boolean }) => (
            <Tag {...p} data-state={state.open ? "open" : "closed"} />
          )}
        >
          {children}
        </Part>
      );
    };
  }
  const Trigger = triggerPart(Base.Trigger, triggerTag, (child) =>
    triggerTag === "button" ? { nativeButton: isNativeButton(child) } : {},
  );

  type ItemProps = Div & {
    onSelect?: (event: Event | React.SyntheticEvent) => void;
    textValue?: string;
    disabled?: boolean;
    asChild?: boolean;
  };
  function Item({ onSelect, onClick, textValue, asChild, children, ...props }: ItemProps) {
    const keepOpen = React.useContext(KeepOpen);
    const handle = (event: React.MouseEvent<HTMLDivElement>) => {
      keepOpen.current = false;
      onClick?.(event);
      onSelect?.(event);
      if (event.defaultPrevented) keepOpen.current = true;
    };
    if (asChild && React.isValidElement(children)) {
      const child = children as React.ReactElement;
      return (
        <Base.Item
          {...(props as object)}
          label={textValue}
          nativeButton={isNativeButton(child)}
          onClick={handle}
          render={child}
        />
      );
    }
    return (
      <Base.Item {...(props as object)} label={textValue} onClick={handle}>
        {children}
      </Base.Item>
    );
  }

  type CheckProps = Omit<Div, "onChange"> & {
    checked?: boolean | "indeterminate";
    onCheckedChange?: (checked: boolean) => void;
    onSelect?: (event: Event | React.SyntheticEvent) => void;
    textValue?: string;
    disabled?: boolean;
  };
  function CheckboxItem({
    checked,
    onCheckedChange,
    onSelect,
    onClick,
    textValue,
    children,
    ...props
  }: CheckProps) {
    const keepOpen = React.useContext(KeepOpen);
    return (
      <KindContext.Provider value="checkbox">
        <Base.CheckboxItem
          {...(props as object)}
          label={textValue}
          checked={checked === undefined ? undefined : checked === true}
          onCheckedChange={(next: boolean) => onCheckedChange?.(next)}
          // Radix closes the menu when a checkbox is chosen; Base UI keeps it open.
          closeOnClick
          onClick={(event: React.MouseEvent<HTMLDivElement>) => {
            keepOpen.current = false;
            onClick?.(event);
            onSelect?.(event);
            if (event.defaultPrevented) keepOpen.current = true;
          }}
          render={(p: Record<string, any>, state: { checked: boolean }) => (
            <div {...p} data-state={state.checked ? "checked" : "unchecked"} />
          )}
        >
          {children}
        </Base.CheckboxItem>
      </KindContext.Provider>
    );
  }

  function RadioGroup({
    onValueChange,
    ...props
  }: Omit<Div, "onChange" | "defaultValue"> & {
    value?: string;
    defaultValue?: string;
    onValueChange?: (value: string) => void;
    disabled?: boolean;
  }) {
    return (
      <Base.RadioGroup
        {...(props as object)}
        onValueChange={(next: string) => onValueChange?.(next)}
      />
    );
  }

  function RadioItem({
    value,
    onSelect,
    onClick,
    textValue,
    children,
    ...props
  }: Div & {
    value: string;
    onSelect?: (event: Event | React.SyntheticEvent) => void;
    textValue?: string;
    disabled?: boolean;
  }) {
    const keepOpen = React.useContext(KeepOpen);
    return (
      <KindContext.Provider value="radio">
        <Base.RadioItem
          {...(props as object)}
          value={value}
          label={textValue}
          closeOnClick
          onClick={(event: React.MouseEvent<HTMLDivElement>) => {
            keepOpen.current = false;
            onClick?.(event);
            onSelect?.(event);
            if (event.defaultPrevented) keepOpen.current = true;
          }}
          render={(p: Record<string, any>, state: { checked: boolean }) => (
            <div {...p} data-state={state.checked ? "checked" : "unchecked"} />
          )}
        >
          {children}
        </Base.RadioItem>
      </KindContext.Provider>
    );
  }

  function ItemIndicator({
    forceMount,
    ...props
  }: React.ComponentProps<"span"> & { forceMount?: boolean }) {
    const kind = React.useContext(KindContext);
    const Part = kind === "radio" ? Base.RadioItemIndicator : Base.CheckboxItemIndicator;
    return <Part {...(props as object)} keepMounted={forceMount} />;
  }

  const SubTrigger = triggerPart(Base.SubmenuTrigger, "div");

  function Label(props: Div) {
    return <div {...props} />;
  }

  return {
    Root,
    Trigger,
    Portal: Base.Portal as React.ComponentType<
      { children?: React.ReactNode } & Record<string, unknown>
    >,
    Content,
    Group: Base.Group as React.ComponentType<Div>,
    Item,
    CheckboxItem,
    RadioGroup,
    RadioItem,
    ItemIndicator,
    Label,
    Separator: Base.Separator as React.ComponentType<Div>,
    Sub,
    SubTrigger,
    SubContent: Content,
  };
}

"use client";
// ROC primitive: shared adapter that gives Base UI's Portal > Positioner > Popup
// parts the shape ROC components use: a single `Content`, `asChild` triggers,
// `data-state`, and the `--roc-popup-*` variables.
import * as React from "react";
import { mergeProps } from "@base-ui/react/merge-props";
import { composeRefs } from "./primitive-utils";

export type Side = "top" | "right" | "bottom" | "left";
export type Align = "start" | "center" | "end";

export type PositionProps = {
  side?: Side;
  align?: Align;
  sideOffset?: number;
  alignOffset?: number;
  collisionPadding?: number;
  /** Set false to keep the popup on its requested side even when it overflows. */
  avoidCollisions?: boolean;
  /** Keep the popup in view while the trigger scrolls out ("always"). */
  sticky?: "partial" | "always";
};

/** Render `child` with Base UI's props merged in, plus `data-state`. */
export function renderChild(
  child: React.ReactElement,
  open: (state: any) => boolean,
  openValue = "open",
  extra?: (state: any) => Record<string, any>,
) {
  return (props: Record<string, any>, state: any) =>
    React.cloneElement(
      child,
      mergeProps(child.props as Record<string, any>, props, {
        "data-state": open(state) ? openValue : "closed",
        ...extra?.(state),
      }) as Record<string, any>,
    );
}

/** Triggers must opt out of native-button behaviour when they render something else. */
export const isNativeButton = (child: React.ReactElement) =>
  typeof child.type !== "string" || child.type === "button";

/** Base UI reports logical sides for submenus; ROC CSS and components use physical ones. */
export function physicalSide(side: string | undefined) {
  if (side !== "inline-start" && side !== "inline-end") return side;
  const rtl =
    typeof document !== "undefined" && document.documentElement.dir === "rtl";
  return (side === "inline-end") !== rtl ? "right" : "left";
}

/** A popup copies its own z-index to the positioner, so stacking matches the CSS. */
function useStackingOf(ref: React.RefObject<HTMLElement | null>) {
  const [zIndex, setZIndex] = React.useState<string>();
  React.useLayoutEffect(() => {
    if (!ref.current) return;
    const value = getComputedStyle(ref.current).zIndex;
    setZIndex(value === "auto" ? undefined : value);
  });
  return zIndex;
}

type Parts = { Positioner: React.ElementType; Popup: React.ElementType };

/**
 * Build a Content component. `prefix` names the CSS variables that Radix-era CSS
 * reads (`--radix-<prefix>-content-transform-origin` and friends).
 */
export function createContent(parts: Parts, prefix: string, openValue = "open") {
  type Props = Omit<React.ComponentProps<"div">, "ref"> &
    PositionProps & {
      ref?: React.Ref<HTMLDivElement>;
      anchor?: Element | null;
      /** Extra props for Base UI's Positioner, such as `alignItemWithTrigger`. */
      positionerProps?: Record<string, unknown>;
      /** Keep mounted while closed. Not needed: Portal handles presence. */
      forceMount?: boolean;
    };
  return function Content({
    side,
    align,
    sideOffset,
    alignOffset,
    collisionPadding,
    avoidCollisions = true,
    sticky,
    anchor,
    positionerProps,
    forceMount: _forceMount,
    style,
    ref,
    children,
    ...props
  }: Props) {
    const popup = React.useRef<HTMLDivElement | null>(null);
    const stacking = useStackingOf(popup);
    return (
      <parts.Positioner
        side={side}
        align={align}
        sideOffset={sideOffset}
        alignOffset={alignOffset}
        collisionPadding={collisionPadding}
        collisionAvoidance={
          avoidCollisions ? undefined : { side: "none", align: "none" }
        }
        sticky={sticky === "always"}
        anchor={anchor ?? undefined}
        {...positionerProps}
        style={{ zIndex: stacking }}
      >
        <parts.Popup
          {...props}
          ref={composeRefs(ref, popup)}
          render={(popupProps: Record<string, any>, state: { open: boolean }) => (
            <div
              {...popupProps}
              data-side={physicalSide(popupProps["data-side"])}
              data-state={state.open ? openValue : "closed"}
            />
          )}
          style={
            {
              [`--radix-${prefix}-content-transform-origin`]: "var(--transform-origin)",
              [`--radix-${prefix}-content-available-height`]: "var(--available-height)",
              [`--radix-${prefix}-content-available-width`]: "var(--available-width)",
              [`--radix-${prefix}-trigger-width`]: "var(--anchor-width)",
              [`--radix-${prefix}-trigger-height`]: "var(--anchor-height)",
              ...style,
            } as React.CSSProperties
          }
        >
          {children}
        </parts.Popup>
      </parts.Positioner>
    );
  };
}

"use client";
// ROC primitive helpers. Small, dependency-free building blocks.
import * as React from "react";

/** Run the caller's handler first; run ours unless the caller prevented default. */
export function composeEventHandlers<E extends { defaultPrevented: boolean }>(
  original: ((event: E) => void) | undefined,
  ours: ((event: E) => void) | undefined,
) {
  return (event: E) => {
    original?.(event);
    if (!event.defaultPrevented) ours?.(event);
  };
}

type PossibleRef<T> = React.Ref<T> | undefined;

/** Merge refs, forwarding React 19 ref cleanups. */
export function composeRefs<T>(...refs: PossibleRef<T>[]): React.RefCallback<T> {
  return (node) => {
    const cleanups: Array<() => void> = [];
    for (const ref of refs) {
      if (typeof ref === "function") {
        const cleanup = ref(node);
        cleanups.push(
          typeof cleanup === "function" ? cleanup : () => ref(null),
        );
      } else if (ref) {
        (ref as React.RefObject<T | null>).current = node;
        cleanups.push(() => {
          (ref as React.RefObject<T | null>).current = null;
        });
      }
    }
    return () => cleanups.forEach((cleanup) => cleanup());
  };
}

export function useComposedRefs<T>(...refs: PossibleRef<T>[]) {
  // eslint-disable-next-line react-hooks/exhaustive-deps
  return React.useCallback(composeRefs(...refs), refs);
}

export function usePrevious<T>(value: T) {
  const ref = React.useRef({ value, previous: value });
  return React.useMemo(() => {
    if (ref.current.value !== value) {
      ref.current.previous = ref.current.value;
      ref.current.value = value;
    }
    return ref.current.previous;
  }, [value]);
}

@import "./ui-base.css";
.roc-ui[data-slot="dropdown-menu-content"],
.roc-ui[data-slot="dropdown-menu-sub-content"] {
  z-index: 50;
  min-width: 180px;
  max-width: calc(100vw - 24px);
  max-height: var(--radix-dropdown-menu-content-available-height);
  overflow: auto;
  padding: 5px;
  border: 1px solid var(--roc-line, #dedede);
  border-radius: var(--roc-radius, 8px);
  background: var(--roc-paper, #fff);
  box-shadow: 0 8px 28px #00000012;
  transform-origin: var(--radix-dropdown-menu-content-transform-origin);
  animation: roc-ui-pop-in var(--roc-motion-fast) var(--roc-motion-ease);
}
.roc-ui[data-slot="dropdown-menu-content"][data-state="closed"],
.roc-ui[data-slot="dropdown-menu-sub-content"][data-state="closed"] {
  animation: roc-ui-pop-out var(--roc-motion-quick) var(--roc-motion-ease);
}
.roc-ui:is(
  [data-slot="dropdown-menu-item"],
  [data-slot="dropdown-menu-checkbox-item"],
  [data-slot="dropdown-menu-radio-item"],
  [data-slot="dropdown-menu-sub-trigger"]
) {
  position: relative;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 9px 10px;
  border-radius: 4px;
  cursor: default;
  user-select: none;
  outline: none;
}
.roc-ui:is(
    [data-slot="dropdown-menu-item"],
    [data-slot="dropdown-menu-checkbox-item"],
    [data-slot="dropdown-menu-radio-item"],
    [data-slot="dropdown-menu-sub-trigger"]
  )[data-highlighted] {
  background: var(--roc-marker, #f1f1f1);
}
.roc-ui[data-slot="dropdown-menu-item"][data-variant="destructive"] {
  color: #b33434;
}
.roc-ui[data-inset="true"],
.roc-ui[data-slot="dropdown-menu-checkbox-item"],
.roc-ui[data-slot="dropdown-menu-radio-item"] {
  padding-left: 32px;
}
.roc-ui[data-slot="dropdown-menu-checkbox-item"] > span:first-child,
.roc-ui[data-slot="dropdown-menu-radio-item"] > span:first-child {
  position: absolute;
  left: 9px;
  display: grid;
  place-items: center;
}
.roc-ui[data-slot="dropdown-menu-radio-item"] svg {
  width: 8px;
  height: 8px;
  fill: currentColor;
}
.roc-ui[data-slot="dropdown-menu-label"] {
  padding: 8px 10px;
  color: var(--roc-muted, #777);
  font-size: 11px;
}
.roc-ui[data-slot="dropdown-menu-separator"] {
  height: 1px;
  margin: 5px 0;
  background: var(--roc-line, #e5e5e5);
}
.roc-ui[data-slot="dropdown-menu-shortcut"] {
  margin-left: auto;
  color: var(--roc-muted, #999);
  font: 10px ui-monospace;
}
.roc-ui[data-slot="dropdown-menu-sub-trigger"] > svg {
  margin-left: auto;
}

/* Shared ROC foundations. No global reset or host stylesheet required. */
.roc-ui {
  box-sizing: border-box;
  font: inherit;
  font-size: 13px;
  color: var(--roc-ink, #252525);
}
.roc-ui *,
.roc-ui *::before,
.roc-ui *::after {
  box-sizing: border-box;
}
.roc-ui:focus-visible {
  outline: 2px solid var(--roc-focus, #737373);
  outline-offset: 3px;
}
.roc-ui:disabled,
.roc-ui[data-disabled] {
  opacity: 0.45;
  cursor: not-allowed;
}
/* Micro-motion scale, adapted from transitions.dev. Override on `.roc-ui`. */
:where(.roc-ui, .roc-shadcn) {
  --roc-motion-quick: 150ms;
  --roc-motion-fast: 250ms;
  --roc-motion-medium: 350ms;
  --roc-motion-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --roc-motion-bounce: cubic-bezier(0.34, 1.36, 0.64, 1);
  --roc-motion-blur: 2px;
}
.roc-ui-icon,
